     3	import java.math.BigDecimal;
     4	import java.util.Optional;
     5	
     6	public enum Coupon {
     7	  WELCOME10 {
     8	    @Override
     9	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
    10	      if (!ctx.isFirstPurchase) return Optional.empty();
    11	      return Optional.of(productsSubtotal.multiply(new BigDecimal("0.10")));
    12	    }
    13	  },
    14	  MINUS50 {
    15	    @Override
    16	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
    17	      if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) return Optional.empty();
    18	      return Optional.of(new BigDecimal("50.00"));
    19	    }
    20	  },
    21	  FREESHIPPING {
    22	    @Override
    23	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
    24	      if (ctx.shippingMethod == ShippingMethod.STORE_PICKUP) return Optional.empty();
    25	      return Optional.of(ctx.shippingCost);
    26	    }
    27	  },
    28	  BUY3PAY2 {
    29	    @Override
    30	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
    31	      BigDecimal discount = BigDecimal.ZERO;
    32	      for (OrderItem item : ctx.items) {
    33	        int freeItems = item.quantity() / 3;
    34	        discount = discount.add(
    35	          new BigDecimal(freeItems).multiply(
    36	            item.price()
    37	          )
    38	        );
    39	      }
    40	      return Optional.of(discount);
    41	    }
    42	  };
    43	
    44	  public abstract Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx);
    45	
    46	  public static Optional<Coupon> fromCode(String code) {
    47	    if (code == null || code.isEmpty()) return Optional.empty();
    48	    try {
    49	      return Optional.of(Coupon.valueOf(code));
    50	    } catch (IllegalArgumentException e) {
    51	      return Optional.empty();
    52	    }
    53	  }
    54	
    55	  public record OrderContext(
    56	    java.util.List<OrderItem> items,
    57	    boolean isFirstPurchase,
    58	    ShippingMethod shippingMethod,
    59	    BigDecimal shippingCost
    60	  ) {}
    61	
