     1	package com.loja.order.service;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import com.fasterxml.jackson.databind.ObjectMapper;
     5	import java.math.BigDecimal;
     6	import java.net.URI;
     7	import java.net.http.HttpClient;
     8	import java.net.http.HttpRequest;
     9	import java.net.http.HttpResponse;
    10	import java.time.Duration;
    11	import org.springframework.beans.factory.annotation.Value;
    12	import org.springframework.stereotype.Service;
    13	
    14	@Service
    15	public class TransLogClient {
    16	  private final String translogUrl;
    17	  private final HttpClient httpClient;
    18	  private final ObjectMapper objectMapper;
    19	
    20	  public TransLogClient(
    21	    @Value("${translog.url:}") String translogUrl,
    22	    ObjectMapper objectMapper
    23	  ) {
    24	    this.translogUrl = translogUrl;
    25	    this.objectMapper = objectMapper;
    26	    this.httpClient = HttpClient.newBuilder()
    27	      .connectTimeout(Duration.ofSeconds(2))
    28	      .build();
    29	  }
    30	
    31	  public record QuoteResponse(BigDecimal price, int etaDays) {}
    32	
    33	  public QuoteResponse quote(String zipCode, int weightGrams, String service) throws Exception {
    34	    if (translogUrl == null || translogUrl.isEmpty()) {
    35	      throw new TransLogUnavailableException();
    36	    }
    37	
    38	    String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    39	      translogUrl, zipCode, weightGrams, service);
    40	
    41	    HttpRequest request = HttpRequest.newBuilder()
    42	      .uri(URI.create(url))
    43	      .GET()
    44	      .timeout(Duration.ofSeconds(2))
    45	      .build();
    46	
    47	    try {
    48	      HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    49	
    50	      if (response.statusCode() != 200) {
    51	        throw new TransLogUnavailableException();
    52	      }
    53	
    54	      JsonNode json = objectMapper.readTree(response.body());
    55	
    56	      if (json.has("error")) {
    57	        throw new ZipCodeNotServedException();
    58	      }
    59	
    60	      if (!json.has("price_cents") || !json.has("eta_hours")) {
    61	        throw new TransLogUnavailableException();
    62	      }
    63	
    64	      long priceCents = json.get("price_cents").asLong();
    65	      int etaHours = json.get("eta_hours").asInt();
    66	
    67	      BigDecimal priceReais = BigDecimal.valueOf(priceCents).divide(
    68	        new BigDecimal("100"),
    69	        2,
    70	        java.math.RoundingMode.HALF_EVEN
    71	      );
    72	
    73	      int etaDays = (int) Math.ceil(etaHours / 24.0);
    74	
    75	      return new QuoteResponse(priceReais, etaDays);
    76	    } catch (java.net.http.HttpTimeoutException | java.net.ConnectException e) {
    77	      throw new TransLogUnavailableException();
    78	    }
    79	  }
    80	
    81	  public static class TransLogUnavailableException extends Exception {}
    82	  public static class ZipCodeNotServedException extends Exception {}
    83	}
