261	  @Transactional
262	  public OrderResponse cancelOrder(Long orderId) throws NotFoundException, OperationNotAllowedException {
263	    Order order = orderRepository.findByIdForUpdate(orderId)
264	      .orElseThrow(() -> new NotFoundException("ORDER_NOT_FOUND"));
265	
266	    if (!order.canBeCancelled()) {
267	      throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
268	    }
