package com.loja.order.controller;

import com.loja.order.dto.*;
import com.loja.order.service.OrderService;
import com.loja.order.service.NotificationService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/")
public class OrderController {
  private final OrderService orderService;
  private final NotificationService notificationService;

  public OrderController(OrderService orderService, NotificationService notificationService) {
    this.orderService = orderService;
    this.notificationService = notificationService;
  }

  @PostMapping("/checkout/summary")
  public ResponseEntity<?> calculateSummary(@RequestBody OrderRequest request) {
    try {
      SummaryResponse summary = orderService.calculateSummary(request);
      return ResponseEntity.ok(summary);
    } catch (OrderService.ValidationException e) {
      return ResponseEntity.status(422).body(new ErrorResponse(e.getMessage()));
    } catch (Exception e) {
      return ResponseEntity.status(503).body(new ErrorResponse("CARRIER_UNAVAILABLE"));
    }
  }

  @PostMapping("/orders")
  public ResponseEntity<?> createOrder(@RequestBody OrderRequest request) {
    try {
      OrderResponse order = orderService.createOrder(request);
      return ResponseEntity.status(201).body(order);
    } catch (OrderService.ValidationException e) {
      return ResponseEntity.status(422).body(new ErrorResponse(e.getMessage()));
    } catch (Exception e) {
      return ResponseEntity.status(503).body(new ErrorResponse("CARRIER_UNAVAILABLE"));
    }
  }

    }
  }

  @GetMapping("/products/{sku}")
  public ResponseEntity<?> getProduct(@PathVariable String sku) {
    try {
      OrderService.ProductDto product = orderService.getProduct(sku);
      ProductResponse response = new ProductResponse(
        product.sku(),
        product.name(),
        product.price(),
        product.weightKg(),
        product.stock(),
        product.discontinued()
      );
      return ResponseEntity.ok(response);
    } catch (OrderService.NotFoundException e) {
      return ResponseEntity.status(404).body(new ErrorResponse(e.getMessage()));
    }
  }

  @GetMapping("/customers/{cpf}")
  public ResponseEntity<?> getCustomer(@PathVariable String cpf) {
    try {
      OrderService.CustomerDto customer = orderService.getCustomer(cpf);
      CustomerResponse response = new CustomerResponse(
        customer.cpf(),
        customer.creditBalance()
      );
      return ResponseEntity.ok(response);
    } catch (OrderService.NotFoundException e) {
      return ResponseEntity.status(404).body(new ErrorResponse(e.getMessage()));
    }
  }

  @GetMapping("/customers/{cpf}/notifications")
package com.loja.order.model;

import com.loja.order.domain.*;
import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "orders")
public class Order {
  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  @Column(name = "id")
  private Long id;

  @Column(name = "customer_cpf", nullable = false, length = 11)
  private String customerCpf;

  @Column(name = "customer_email", nullable = false)
  private String customerEmail;

  @Enumerated(EnumType.STRING)
  @Column(name = "status", nullable = false)
  private OrderStatus status;

  @Column(name = "created_at", nullable = false)
  private Instant createdAt;

  private String transactionId;

  @Column(name = "paid_at")
  private Instant paidAt;

  @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
  private List<OrderItem> items = new ArrayList<>();

  @Embedded
  private OrderSummary summary;

  protected Order() {}

  public Order(
    String customerCpf,
    String customerEmail,
    Region region,
    ShippingMethod shippingMethod,
    String zipCode,
    PaymentMethod paymentMethod,
    int installments,
    ClubTier clubTier,
    String coupon
  ) {
    this.customerCpf = customerCpf;
    this.customerEmail = customerEmail;
    this.status = OrderStatus.AWAITING_PAYMENT;
    this.createdAt = Instant.now();
    this.region = region;
    this.shippingMethod = shippingMethod;
    this.zipCode = zipCode;
    this.paymentMethod = paymentMethod;
    this.installments = installments;
    this.clubTier = clubTier;
    this.coupon = coupon;
  }

  public void setSummary(OrderSummary summary) {
    this.summary = summary;
  }

  public void addItem(String sku, int quantity, BigDecimal price) {
    OrderItem item = new OrderItem(sku, quantity, price);
    item.setOrder(this);
    items.add(item);
  }

  public void markAsPaid(String transactionId, Instant paidAt) {
    this.transactionId = transactionId;
    this.paidAt = paidAt;
    this.status = OrderStatus.PAID;
  }

  public void markAsShipped(String trackingCode) {
    this.trackingCode = trackingCode;
    this.status = OrderStatus.SHIPPED;
  }

  public void markAsDelivered() {
    this.status = OrderStatus.DELIVERED;
  }

  public void cancel() {
    this.status = OrderStatus.CANCELLED;
  }

  public Long getId() {
    return id;
  }

  public String getCustomerCpf() {
    return customerCpf;
  }

  public String getCustomerEmail() {
    return customerEmail;
  }

  public OrderStatus getStatus() {
    return status;
  }

